-- Paladin class quests: one race's chain per character.
--
-- mod-uac (any race, any class) opens each race's paladin chain to the
-- whole faction (mod_uac_quest_template.sql, its "faction unlock"), so an
-- off-race paladin can travel to whichever chain is nearest. Nothing then
-- stops a paladin who finished one chain from doing the others: Human,
-- Dwarf and Draenei paladins each have their own Tome of Divinity /
-- Redemption chain with the same rewards, and players reported repeating
-- them at the other races' quest givers.
--
-- Rule: once any quest of one chain is in the log or turned in, every
-- quest of the other chains is unavailable. QUEST_AVAILABLE conditions
-- (CONDITION_QUESTSTATE 47, mask 74 = complete | in progress | rewarded,
-- negated) -- ElseGroup 0, so they AND with the chains' own conditions.
-- The repeatable Tome/Symbol of Life turn-ins are left alone. Idempotent.
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 19 AND `ConditionTypeOrReference` = 47
    AND `Comment` LIKE 'nekocore: paladin chain%' AND `SourceEntry` IN (1642, 1643, 1644, 1646, 1647, 1648, 1778, 1779, 1780, 1781, 1783, 1784, 1785, 1786, 1787, 1788, 2997, 2998, 2999, 3000, 3101, 3107, 3681, 9598, 9600, 10366);

INSERT INTO `conditions` (`SourceTypeOrReferenceId`, `SourceGroup`, `SourceEntry`, `SourceId`, `ElseGroup`,
    `ConditionTypeOrReference`, `ConditionTarget`, `ConditionValue1`, `ConditionValue2`, `ConditionValue3`,
    `NegativeCondition`, `ErrorType`, `ErrorTextId`, `ScriptName`, `Comment`) VALUES
